 const fetchedMarkets=new Map();
 function marketIds(){return [...new Set([currentRecipe.id,...lastResult.bill.map(m=>m.id),...(cfg.withJournals&&lastResult.journals?.supported?[lastResult.journals.empty,lastResult.journals.full]:[]),...window.HeartsUI.marketIds(lastResult),...window.FoodSauceUI.marketIds(currentRecipe,cfg,D)])]}
 function marketKey(){return [state.server,currentRecipe.id,cfg.quality,...marketIds().sort()].join('|')}
 function scheduleMarketRefresh(){
  clearTimeout(refreshTimer);refreshTimer=null;
  const key=marketKey();
  if(loadingKey===key)return;
  refreshSeq++;refreshController?.abort();loadingKey=null;
  $('refresh').disabled=false;$('refresh').textContent='↻ Обновить цены';
  if(Date.now()-(fetchedMarkets.get(key)||0)<300000){renderSaleStatus();return}
  $('sale-status').innerHTML='<p class="hint">Загружаем цены выбранного предмета и ингредиентов…</p>';
  refreshTimer=setTimeout(()=>refresh(),350);
 }
 function renderSaleStatus(sale=saleQuote(currentRecipe.id,cfg.sellCity,cfg.quality,cfg.saleMode)){
  if(loadingKey===marketKey()||refreshTimer){$('sale-status').innerHTML='<p class="hint">Загружаем цены выбранного предмета и ингредиентов…</p>';return}
  if(cfg.manualSale){$('sale-status').innerHTML='<p class="hint">Цена продажи задана вручную и сохранена.</p>';return}
  if(sale.price){$('sale-status').innerHTML=`<p class="hint">${cfg.saleMode==='discord'?'Средняя цена истории':'Проверенная цена ордера'}: ${money(sale.price)} · ${esc(cfg.sellCity)}.</p>`;return}
  const reason=sale.reason==='Нет цены'?'Источник не вернул ордер для выбранного города и качества.':sale.reason==='Недостаточно свежей истории для проверки цены'?'Ордер есть, но свежей истории недостаточно для проверки цены.':sale.reason==='Устаревшая цена'?'Ордер старше допустимого срока.':sale.reason==='Подозрительная цена'?'Цена ордера отклоняется от истории или других городов и исключена.':sale.reason;
  const options=supportedSaleCities().filter(c=>c!==cfg.sellCity).map(city=>({city,q:saleQuote(currentRecipe.id,city,cfg.quality,cfg.saleMode)})).filter(x=>x.q.price>0);
  $('sale-status').innerHTML=`<p class="hint">${esc(reason||'Нет подтверждённой цены')}${sale.raw>0?' Ордер источника: '+money(sale.raw)+'.':''}</p>`+(options.length?'<p class="hint">Цена доступна в других городах. Выберите город продажи:</p><div class="price-cities">'+options.map(({city,q})=>`<button type="button" class="button" data-price-city="${esc(city)}">${esc(city)} · ${fmt(q.price)}</button>`).join('')+'</div>':'<p class="hint">В доступных данных нет проверенной цены для этого варианта. Можно обновить данные или ввести цену из игры вручную.</p>');
 }
