 $('compare').onclick=()=>{let ranked=[];for(const r of D.recipes.filter(x=>(x.kind===state.mode||state.mode==='gear'&&x.kind==='bags')&&(state.mode!=='gear'||x.id===currentRecipe.id))){const c={...cfg,chain:false,refineSteps:{},foodIngredientSteps:{},makeSauce:false,unitFee:r.fee300,eff:cfg.focusSource==='levels'?window.MasteryMath.efficiency(r,window.MasteryUI.levels(),window.MASTERY_DATA):cfg.eff};if(!placeReady())continue;c.rrr=cfg.craftPlace==='hideout'?E.hideoutReturn(cfg.hideoutBaseReturn,cfg.focus):E.returnRate(r.kind,cfg.craftCity,cfg.focus,r.category,cfg.craftPlace,cfg.dailyBonus);for(const city of supportedSaleCities()){const h=history(r.id,city,cfg.quality),q=saleQuote(r.id,city,cfg.quality,cfg.saleMode);if(!q.price)continue;c.salePrice=q.price;const z=E.calculate(r,c,D,cheapest);if(z.missing||z.stale||!z.amount||state.mode!=='gear'&&z.amount>h.daily*Math.max(.01,cfg.cycleDays))continue;ranked.push({r,city,z,h})}}ranked.sort((a,b)=>b.z.profit-a.z.profit);$('ranking').innerHTML=ranked.slice(0,18).map(x=>`<tr><td class="name"><div class="item-with-icon">${window.ItemIcons.image(x.r.id,cfg.quality,40)}<span class="item-copy">${esc(x.r.name)}<small>${x.r.tier}.${x.r.ench}</small></span></div></td><td>${x.city}</td><td>${fmt(x.z.amount)}</td><td class="${x.z.profit>0?'positive':'negative'}"><b>${money(x.z.profit)}</b></td><td>${x.h?fmt(x.h.daily):'—'}</td><td>${x.h?.daily?fmt(x.z.amount/(x.h.daily*3)*100,1)+'%':'—'}</td><td><button class="button" data-pick="${esc(x.r.id)}" data-sell="${x.city}">Выбрать</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Нет вариантов с полным набором свежих цен без выбросов.</td></tr>'};
 $('ranking').onclick=e=>{const b=e.target.closest('[data-pick]');if(!b)return;chooseRecipe(b.dataset.pick);cfg.sellCity=b.dataset.sell;$('sell-city').value=cfg.sellCity;saleFromMarket();persist();render();$('title').scrollIntoView({behavior:'smooth'})};
 $('reset').onclick=()=>{localStorage.removeItem(KEY);location.reload()};switchMode(state.mode);

$('theme').replaceChildren(...window.AppearanceThemes.entries.map(([id,label])=>new Option(label,id)));
function applyTheme(){const theme=window.AppearanceThemes.normalize(state.theme);if(state.theme!==theme){state.theme=theme;persist();}document.documentElement.dataset.theme=theme;$('theme').value=theme;}
$('theme').onchange=()=>{state.theme=$('theme').value;applyTheme();persist()};applyTheme();
if(state.lastUpdate)$('data-status').textContent='Последняя загрузка выбранных позиций · '+new Date(state.lastUpdate).toLocaleString('ru-RU');

document.addEventListener('masterychange',()=>{render();persist()});
document.addEventListener('pricebookchange',()=>{render();persist()});
window.CraftApp={navigate:mode=>{switchMode(mode);document.dispatchEvent(new Event('change'));},saveConfig:patch=>{Object.assign(cfg,patch);persist();render();scheduleMarketRefresh();},snapshot:()=>({recipe:currentRecipe,config:{...cfg},result:lastResult,server:state.server,placeReady:placeReady()}),quote:(server,id,city,q)=>server===state.server?quoteRow(id,city,q):null,history:(server,id,city,q)=>server===state.server?history(id,city,q):null,open(id,patch={}){const r=D.recipes.find(r=>r.id===id);if(!r)return;switchMode(r.kind);chooseRecipe(id);Object.assign(cfg,patch);automaticReturn();rememberStation();for(const [id,key]of Object.entries(fields)){if($(id).type==='checkbox')$(id).checked=cfg[key];else $(id).value=cfg[key]??''}render();persist();scheduleMarketRefresh();document.dispatchEvent(new Event('change'));}};

// A tab owns only its calculation; profiles, libraries and preferences remain shared.
CraftApp.defaultDraft=id=>{const r=D.recipes.find(x=>x.id===id);if(!r)throw Error('Предмет не найден.');const mode=r.kind==='bags'?'gear':r.kind,config=defaults(r);config.manualReturn=false;config.rrr=config.craftPlace==='hideout'?E.hideoutReturn(config.hideoutBaseReturn,config.focus):E.returnRate(mode,config.craftCity,config.focus,r.category,config.craftPlace,config.dailyBonus);return {mode,recipeId:r.id,config,overrides:{},craftSites:{},stationTariffs:{},search:''};};
CraftApp.cancelMarket=()=>{clearTimeout(refreshTimer);refreshTimer=null;refreshSeq++;refreshController?.abort();loadingKey=null;$('refresh').disabled=false;$('refresh').textContent='↻ Обновить цены';};
CraftApp.captureDraft=()=>{const config=ScenarioMath.clone(cfg);delete config.masteryLevels;delete config.focusOverrides;return ScenarioMath.clone({mode:state.mode,recipeId:currentRecipe.id,config,overrides:state.overrides,craftSites:state.craftSites||{},stationTariffs:state.stationTariffs||{},search:$('search').value});};
CraftApp.restoreDraft=(draft,server)=>{
 CraftApp.cancelMarket();const r=D.recipes.find(x=>x.id===draft.recipeId);if(!r)throw Error('Предмет отсутствует в каталоге. Выберите замену.');
 state.workspaceMarkets||={};state.workspaceMarkets[state.server]={quotes:state.quotes,histories:state.histories,lastUpdate:state.lastUpdate||null};const market=ScenarioMath.clone(state.workspaceMarkets[server]||{quotes:{},histories:{},lastUpdate:null});state.server=server;state.quotes=market.quotes;state.histories=market.histories;state.lastUpdate=market.lastUpdate;state.drafts={};state.overrides=ScenarioMath.clone(draft.overrides||{});state.craftSites=ScenarioMath.clone(draft.craftSites||{});state.stationTariffs=ScenarioMath.clone(draft.stationTariffs||{});
 state.selected[r.kind==='bags'?'gear':r.kind]=r.id;state.drafts[(r.kind==='bags'?'gear':r.kind)+'|'+r.id]=ScenarioMath.clone(draft.config);$('server').value=server;switchMode(r.kind==='bags'?'gear':r.kind);
 cfg={...defaults(r),...ScenarioMath.clone(draft.config)};state.drafts[state.mode+'|'+r.id]=cfg;syncRecipePicker();for(const [id,key]of Object.entries(fields)){if($(id).type==='checkbox')$(id).checked=cfg[key];else $(id).value=cfg[key]??'';}if(draft.search){$('search').value=draft.search;recipeOptions(productKey(r));}render();persist();scheduleMarketRefresh();
};
CraftApp.setCategoryFilter=category=>{const option=[...$('craft-category').options].find(o=>o.value===category);if(!option)throw Error('Категория отсутствует.');$('craft-category').value=category;recipeOptions();};
